import urllib.request
import urllib.error
import time


class RateLimitError(Exception):
    pass


class ServerError(Exception):
    pass


class ClientError(Exception):
    pass


class ConnectionError(Exception):
    pass


class APIClient:
    def __init__(self, base_url: str, timeout: int = 10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path: str) -> str:
        url = self.base_url + path
        return self._request_with_retries(url, method='GET')

    def _request_with_retries(self, url: str, method: str = 'GET') -> str:
        # For 5xx errors: retry once after 1s
        # For 429 errors: retry up to 3 times with exponential backoff (0.5s, 1s, 2s)
        # For network errors: retry once after 1s
        # For 4xx (except 429): raise immediately

        # Track retries for different error types
        max_5xx_retries = 1
        max_429_retries = 3
        max_network_retries = 1

        # Counters
        retry_5xx = 0
        retry_429 = 0
        retry_network = 0

        while True:
            try:
                req = urllib.request.Request(url)
                response = urllib.request.urlopen(req, timeout=self.timeout)
                body = response.read().decode('utf-8')
                status = response.getcode()

                if 200 <= status < 300:
                    return body
                elif status == 429:
                    retry_429 += 1
                    if retry_429 > max_429_retries:
                        raise RateLimitError(f"Rate limit exceeded after {max_429_retries} retries")
                    backoff = 0.5 * (2 ** (retry_429 - 1))  # 0.5, 1, 2
                    time.sleep(backoff)
                    continue
                elif 500 <= status < 600:
                    retry_5xx += 1
                    if retry_5xx > max_5xx_retries:
                        raise ServerError(f"Server error after {max_5xx_retries} retries")
                    time.sleep(1)
                    continue
                elif 400 <= status < 500:
                    raise ClientError(f"Client error: {status}")
                else:
                    # Other status codes, just return body
                    return body

            except urllib.error.HTTPError as e:
                status = e.code
                if status == 429:
                    retry_429 += 1
                    if retry_429 > max_429_retries:
                        raise RateLimitError(f"Rate limit exceeded after {max_429_retries} retries")
                    backoff = 0.5 * (2 ** (retry_429 - 1))  # 0.5, 1, 2
                    time.sleep(backoff)
                    continue
                elif 500 <= status < 600:
                    retry_5xx += 1
                    if retry_5xx > max_5xx_retries:
                        raise ServerError(f"Server error after {max_5xx_retries} retries")
                    time.sleep(1)
                    continue
                elif 400 <= status < 500:
                    raise ClientError(f"Client error: {status}")
                else:
                    raise

            except urllib.error.URLError as e:
                retry_network += 1
                if retry_network > max_network_retries:
                    raise ConnectionError(f"Connection error after {max_network_retries} retries") from e
                time.sleep(1)
                continue
